(function($) {
    'use strict';

    $(document).ready(function() {
        console.log('Custom Circular Residents JS initialized');

        // The IDs are generated by Django as 'id_<field_name>'
        var typeSelector = '#id_types_residents';
        var residentSelector = '#id_residents';

        // Using delegation to handle elements that might be updated by Select2 or other scripts
        $(document).on('change', typeSelector, function() {
            var $typeSelect = $(this);
            var typeId = $typeSelect.val();
            var $residentSelect = $(residentSelector);
            
            console.log('Type change detected. Selected ID:', typeId);

            // 1. Clear the residents field immediately to provide feedback
            $residentSelect.empty().trigger('change');

            if (typeId) {
                console.log('Requesting residents for type_id:', typeId);
                $.ajax({
                    url: '/administrative/ajax/get-residents-by-type/',
                    data: { 'type_id': typeId },
                    dataType: 'json',
                    success: function(data) {
                        console.log('AJAX Success. Received:', data.length, 'residents.');
                        
                        // 2. Clear and populate with new data
                        $residentSelect.empty();
                        
                        // Add a placeholder if it's not a multiple select
                        if (!$residentSelect.prop('multiple')) {
                            $residentSelect.append(new Option('---------', ''));
                        }
                        
                        $.each(data, function(index, resident) {
                            var displayText = resident.name + ' (' + resident.email + ')';
                            $residentSelect.append(new Option(displayText, resident.id, false, false));
                        });

                        // 3. CRITICAL: Trigger change and Select2 specific change to refresh UI
                        $residentSelect.trigger('change');
                        if ($residentSelect.data('select2')) {
                            $residentSelect.trigger('change.select2');
                        }
                        
                        console.log('Resident list updated and Select2 notified.');
                    },
                    error: function(xhr, status, error) {
                        console.error('AJAX Error in get_residents_by_type:', status, error);
                        console.log('Server response:', xhr.responseText);
                    }
                });
            }
        });
    });
})(django.jQuery || jQuery);
